cd /tmp/specwork_fileinfo && cat > scan.py <<'EOF'
import subprocess, re, sys, os

EXE = "/workspace/executable"
MK = "/workspace/tools/makeelf.py"

def run(args, name="scan_tmp"):
    elf = name + ".elf"
    subprocess.run(["python3", MK, elf] + args, check=True, capture_output=True)
    p = subprocess.run([EXE, elf], capture_output=True, text=True)
    html = None
    hp = elf + ".html"
    if os.path.exists(hp):
        html = open(hp).read()
        os.remove(hp)
    os.remove(elf)
    return p, html

def row(html, cls):
    m = re.search(r"<tr class='%s'>.*?</tr>" % re.escape(cls), html, re.S)
    return m.group(0) if m else None

def td(html, cls):
    r = row(html, cls)
    if r is None: return "<no row>"
    m = re.search(r"<td>(.*?)</td> <td>(.*?)</td>", r, re.S)
    return m.group(2) if m else r

mode = sys.argv[1]
if mode == "class":
    for v in range(256):
        p, html = run(["--raw-ehdr-override", "4:%02x" % v])
        if p.returncode != 0:
            print(v, "ERR", p.stderr.strip() or p.stdout.strip())
        else:
            print(v, repr(td(html, "fileinfo_class")))
elif mode == "data":
    for v in range(256):
        p, html = run(["--raw-ehdr-override", "5:%02x" % v])
        if p.returncode != 0:
            print(v, "ERR", p.stderr.strip() or p.stdout.strip())
        else:
            print(v, repr(td(html, "fileinfo_data")))
elif mode == "osabi":
    for v in range(256):
        p, html = run(["--raw-ehdr-override", "7:%02x" % v])
        if p.returncode != 0:
            print(v, "ERR", p.stderr.strip() or p.stdout.strip())
        else:
            print(v, repr(td(html, "fileinfo_abi")))
elif mode == "etype":
    vals = list(range(0x21)) + [0xfe00,0xfe0f,0xfe10,0xfeff,0xff00,0xff10,0xffff,0x1234,0xabcd,0x100]
    for v in vals:
        p, html = run(["--set", "e_type=%d" % v])
        if p.returncode != 0:
            print(hex(v), "ERR", p.stderr.strip() or p.stdout.strip())
        else:
            print(hex(v), repr(td(html, "fileinfo_e_type")))
elif mode == "emachine":
    vals = list(range(301)) + [0x3e8, 0xffff, 0x13f, 0x3e7]
    for v in vals:
        p, html = run(["--set", "e_machine=%d" % v])
        if p.returncode != 0:
            print(v, "ERR", p.stderr.strip() or p.stdout.strip())
        else:
            print(v, repr(td(html, "fileinfo_e_machine")))
